def encode(message):
    encoded_message = ""
    vowels = "aeiouAEIOU"
    for char in message:
        if char.isalpha():
            if char.islower():
                encoded_message += char.upper()
            else:
                encoded_message += char.lower()
            if char in vowels:
                index = vowels.index(char)
                encoded_message += vowels[(index + 2) % len(vowels)]
        else:
            encoded_message += char
    return encoded_message


